/**
 * Past Papers corpus — SERVER-ONLY access to the syllabai-pastpapers index.
 *
 * The corpus repo is ~4 GB of canonical PDFs we NEVER clone or vendor. The
 * committed index (src/data/pastpapers-index.json, generated by
 * scripts/build_pastpapers_index.ts from the git tree) holds the inventory:
 * which paper dirs exist per specification, and which materials (qp.pdf /
 * ms.pdf / er.pdf) each holds. PDFs themselves stream at runtime from
 * raw.githubusercontent.com (CORS-enabled) so the demo hosts nothing.
 *
 * This module imports the index JSON — import it ONLY from server
 * components; client components use @/lib/pastpapers-shared instead.
 *
 * Honesty rules (non-negotiable, demo discipline):
 *   - Corpus metadata is AI-IDENTIFIED (operator ratification pending) — the
 *     index is derived from the canonical layout, full manifests live in the
 *     corpus repo. Every surface says so.
 *   - Official exam durations are shown ONLY where attested in
 *     OFFICIAL_DURATIONS; anything else is an editable estimate labelled as
 *     such in the mock runner.
 *   - Interactive (Mode 2) papers exist ONLY where the parsed question corpus
 *     attests them (sourcePaper provenance, lib/past-papers.ts); everything
 *     else gets the honest "parsing roadmap" state, never a fake player.
 */
import indexJson from "@/data/pastpapers-index.json";
import { parseReconstruction } from "@/lib/pastpapers-reconstruction";
import {
  corpusRawPath,
  ialUnitTitle,
  sessionRankOf,
  specTitle,
  type CorpusIndexMeta,
  type CorpusPaper,
  type CorpusPaperEntry,
  type CorpusSession,
  type CorpusSpec,
} from "@/lib/pastpapers-shared";

// ── index (server-side) ────────────────────────────────────────────────────
interface CorpusIndex {
  meta: CorpusIndexMeta;
  specs: Record<string, CorpusSpec>;
}

export const corpusIndex = indexJson as unknown as CorpusIndex;
export {
  corpusRawUrl,
  corpusRawPath,
  sessionLabel,
  groupBySession,
  prettyBytes,
  specTitle,
} from "@/lib/pastpapers-shared";
export type { CorpusPaperEntry } from "@/lib/pastpapers-shared";

// ── course → corpus mapping ────────────────────────────────────────────────
/** Which corpus specs a demo course draws from, plus optional filters. */
interface CourseSpecMap {
  specs: string[];
  /** Retired specs surfaced in the SAME archive, badged "Legacy spec"
   *  (e.g. 4CH0 papers predate the 4CH1 course). Kept separate from
   *  `specs` so the current-spec mapping stays the primary identity. */
  legacySpecs?: string[];
  /** IAL maths 2018 lives in ONE spec folder — filter by unit code prefix. */
  units?: string[];
  /** 4MA1 tier filter: "F" (foundation) or "H" (higher). */
  tier?: "F" | "H";
  /** Per-science split of one corpus spec — 4SD0's three sciences share the
   *  spec folder (1B/1C/1P + R variants; the qualification has no Paper 2s),
   *  so each demo course filters to its own science's variants. Also used for
   *  the double-award courses' legacySpecs: 4SC0-era physics = 4PH0 1-series
   *  (the legacy Double Award comprised ONLY the three Paper 1s — spec Issue 3). */
  variants?: string[];
}

