  "4PH1/1P": 120, "4PH1/1PR": 120, "4PH1/2P": 75, "4PH1/2PR": 75,
  "4BI1/1B": 120, "4BI1/1BR": 120, "4BI1/2B": 75, "4BI1/2BR": 75,
